using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Security.Cryptography;
namespace PZ3D {
 static class ReadonlySqlite {
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_open_v2(byte[] f,out IntPtr db,int flags,IntPtr vfs);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_close(IntPtr db);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_prepare_v2(IntPtr db,byte[] sql,int bytes,out IntPtr statement,IntPtr tail);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_step(IntPtr statement);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_finalize(IntPtr statement);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_column_count(IntPtr statement);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern IntPtr sqlite3_column_text(IntPtr statement,int column);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_column_bytes(IntPtr statement,int column);
  static byte[] Z(string text){return Encoding.UTF8.GetBytes(text+"\0");}
  public static List<string[]> Query(string file,string sql){LauncherMaintenance.NoReparse(file);string uri=new Uri(Path.GetFullPath(file)).AbsoluteUri+"?mode=ro&immutable=1";IntPtr db=IntPtr.Zero,statement=IntPtr.Zero;try{if(sqlite3_open_v2(Z(uri),out db,1|64,IntPtr.Zero)!=0)throw new Exception("原版服务器收藏数据库无法只读打开。");if(sqlite3_prepare_v2(db,Z(sql),-1,out statement,IntPtr.Zero)!=0)throw new Exception("原版服务器收藏数据库结构尚不支持。");var rows=new List<string[]>();int result;while((result=sqlite3_step(statement))==100){if(rows.Count>=400)throw new Exception("原版收藏条目超过显示限制。");int count=sqlite3_column_count(statement);if(count>32)throw new Exception("原版收藏字段数量异常。");var row=new string[count];for(int column=0;column<count;column++){int length=sqlite3_column_bytes(statement,column);if(length>16000)throw new Exception("原版收藏字段超出容量限制。");IntPtr text=sqlite3_column_text(statement,column);byte[] bytes=new byte[length];if(length>0&&text!=IntPtr.Zero)Marshal.Copy(text,bytes,0,length);row[column]=new UTF8Encoding(false,true).GetString(bytes);}rows.Add(row);}if(result!=101)throw new Exception("原版数据库查询未完成。");return rows;}finally{if(statement!=IntPtr.Zero)sqlite3_finalize(statement);if(db!=IntPtr.Zero)sqlite3_close(db);}}
 }
 static class GameFavorites {
  sealed class Favorite {public string id,name,host,username,userPassword,serverPassword,description,sourceFile,sourceStamp;public int port;public bool relay;}
  static string Hash(string text){return DlssInstaller.Hash(Encoding.UTF8.GetBytes(text));}
  static void CheckSidecars(string file){foreach(string suffix in new[]{"-journal","-wal"}){string path=file+suffix;LauncherMaintenance.NoReparse(path);if(File.Exists(path)&&new FileInfo(path).Length>0)throw new Exception("原版收藏数据库正在写入，请退出游戏后再刷新或导入。");}}
  static List<Favorite> Read(Engine e,List<string> warnings){var all=new List<Favorite>();foreach(string source in new[]{"ServerListSteam.db","ServerList.db"}){string file=Path.Combine(e.User,"db",source);LauncherMaintenance.NoReparse(file);if(!File.Exists(file))continue;try{using(var databaseLock=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){if(new FileInfo(file).Length>16*1024*1024)throw new Exception("原版收藏数据库超过读取容量限制。");foreach(string suffix in new[]{"-journal","-wal"}){LauncherMaintenance.NoReparse(file+suffix);if(File.Exists(file+suffix)&&new FileInfo(file+suffix).Length>0)throw new Exception("原版收藏数据库正在写入，请退出游戏后再导入。");}string stamp=DlssInstaller.HashFile(file);var serverColumns=new HashSet<string>(ReadonlySqlite.Query(file,"PRAGMA table_info(server)").Select(r=>r[1]),StringComparer.OrdinalIgnoreCase);var accountColumns=new HashSet<string>(ReadonlySqlite.Query(file,"PRAGMA table_info(account)").Select(r=>r[1]),StringComparer.OrdinalIgnoreCase);if(!new[]{"id","name","ip","port"}.All(serverColumns.Contains))throw new Exception("原版收藏 server 结构未核实。");Func<string,string> sv=k=>serverColumns.Contains(k)?"s.\""+k+"\"":"''";bool accounts=new[]{"id","serverId","username"}.All(accountColumns.Contains);Func<string,string> av=k=>accounts&&accountColumns.Contains(k)?"a.\""+k+"\"":"''";string sql="SELECT s.id,s.name,s.ip,s.port,"+sv("serverPassword")+","+sv("description")+","+av("id")+","+av("username")+","+av("password")+","+av("isSavePassword")+","+av("isUseSteamRelay")+","+av("authType")+" FROM server s"+(accounts?" LEFT JOIN account a ON a.serverId=s.id":"")+" ORDER BY s.id"+(accounts?",a.id":"")+" LIMIT 201";var rows=ReadonlySqlite.Query(file,sql);CheckSidecars(file);if(stamp!=DlssInstaller.HashFile(file))throw new Exception("原版收藏读取期间改变，请刷新。");foreach(var row in rows.Take(200)){int port;if(!int.TryParse(row[3],out port)||port<1||port>65535||row[1].Length>120||row[2].Length>253||row[7].Length>128||row[4].Length>1024||row[8].Length>1024){warnings.Add("已跳过格式异常的原版收藏。");continue;}if(row[11]!=""&&row[11]!="1"){warnings.Add("已跳过非普通账号认证的收藏；请在游戏内登录。");continue;}all.Add(new Favorite{sourceFile=file,sourceStamp=stamp,id=Hash(source+"|"+stamp+"|"+row[0]+"|"+row[6]),name=row[1],host=row[2],port=port,username=row[7],serverPassword=row[4],userPassword=row[9]=="1"?row[8]:"",description=row[5].Length<=2000?row[5]:row[5].Substring(0,2000),relay=row[10]=="1"});}if(rows.Count>200)warnings.Add("原版收藏超过200项，部分条目未显示。");}}catch(Exception ex){warnings.Add(source+"："+ex.Message);}}return all;}
  public static object List(Engine e){var warnings=new List<string>();var rows=Read(e,warnings);return new{favorites=rows.Select(r=>new{id=r.id,name=r.name,host=r.host,port=r.port,username=r.username,hasUserPassword=r.userPassword!="",hasServerPassword=r.serverPassword!="",useSteamRelay=r.relay}).ToArray(),message=string.Join("\n",warnings)};}
  public static object Import(Engine e,ServerProfiles profiles,string id,bool confirmed){if(!confirmed)throw new Exception("导入原版收藏需要明确确认。");var rows=Read(e,new List<string>());var r=rows.SingleOrDefault(row=>row.id==id);if(r==null)throw new Exception("原版收藏已改变或不存在，请刷新后再导入。");using(var databaseLock=new FileStream(r.sourceFile,FileMode.Open,FileAccess.Read,FileShare.Read)){CheckSidecars(r.sourceFile);if(DlssInstaller.HashFile(r.sourceFile)!=r.sourceStamp)throw new Exception("原版收藏在导入前改变，请刷新。");var list=LauncherNativeState.Json.Deserialize<Dictionary<string,object>>(LauncherNativeState.Json.Serialize(profiles.List()));profiles.Upsert(new Dictionary<string,object>{{"id",""},{"stamp",list["stamp"]},{"name",r.name},{"host",r.host},{"port",r.port},{"queryPort",0},{"username",r.username},{"userPassword",r.userPassword},{"serverPassword",r.serverPassword},{"useSteamRelay",r.relay},{"description",r.description}});return new{message="已导入到启动器的独立服务器列表；未修改原版数据库。请核对角色账号后连接。"};}}
 }
